from machine import Pin
import time


class HX711:
    def __init__(self, dout, pd_sck, gain_pulses=1):
        self.sck = Pin(pd_sck, Pin.OUT, value=0)
        self.dout = Pin(dout, Pin.IN)
        self.extra = gain_pulses  # 1 = channel A, gain 128

    def read(self):
        t = time.ticks_ms()
        while self.dout.value():
            if time.ticks_diff(time.ticks_ms(), t) > 500:
                raise OSError('HX711 not ready: check DOUT and power')
        v = 0
        for _ in range(24):
            self.sck.value(1)
            self.sck.value(0)
            v = (v << 1) | self.dout.value()
        for _ in range(self.extra):
            self.sck.value(1)
            self.sck.value(0)
        return v - 0x1000000 if v & 0x800000 else v
